Description: This Terraform configuration creates a basic AWS RDS MySQL instance. It includes a new VPC, two public subnets across availability zones, an internet gateway, route table, security group allowing MySQL access, a DB subnet group, and a single RDS instance.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to deploy resources into"
  type        = string
  default     = "us-east-1"
}

variable "db_name" {
  description = "Initial database name"
  type        = string
  default     = "basicdb"
}

variable "db_username" {
  description = "Master username for the RDS instance"
  type        = string
  default     = "adminuser"
}

variable "db_password" {
  description = "Master password for the RDS instance"
  type        = string
  sensitive   = true
  default     = "ChangeMe12345!"
}

variable "allowed_cidr" {
  description = "CIDR block allowed to connect to MySQL"
  type        = string
  default     = "0.0.0.0/0"
}

